/**
 * Pure classification logic: a faithful TypeScript port of outagewatch.py
 * (probe() state rules, Monitor, Automation, impact, copilot_note, diagnose, stress_score).
 *
 * No DOM, no network, no clock: everything here is deterministic and unit-tested
 * (tests/classify.test.ts and the cross-check against golden cases generated by the REAL
 * Python code in tests/golden/golden.json).
 *
 * The Power Automate flow stores RAW facts only (HTTP status, elapsed ms, error kind).
 * All judgement happens here, in the browser.
 */

export type RawState = 'up' | 'degraded' | 'down' | 'blocked' | 'unconfigured'
export type State = 'up' | 'warning' | 'suspect' | 'down' | 'blocked' | 'unconfigured'
/** States that are NOT a failure: never freeze, never "at risk", never an incident (NEUTRAL in outagewatch.py). */
export const NEUTRAL: ReadonlySet<string> = new Set(['blocked', 'unconfigured'])
export type Level = 'ok' | 'caution' | 'freeze'

/** One raw probe fact, exactly as the flow wrote it. */
export interface RawResult {
  name: string
  /** HTTP status of the answer; null when there was no HTTP answer at all (DNS, TLS, timeout...). */
  httpStatus: number | null
  elapsedMs: number
  /** Raw error/"code" string of the failed flow action, '' or null when the action succeeded. */
  errorKind: string | null
}

export interface TargetSpec {
  name: string
  /** null = any answer below 500 that is not 429 counts as alive. */
  alive: number[] | null
  dependsOnAuth: boolean
  copilotNeeds: boolean
  /** True for a tenant-specific target that has no URL yet (no tenant name given): shown as "unconfigured", never probed. */
  unconfigured?: boolean
  family?: string
}

export interface Thresholds {
  confirm: number
  window: number
  minHistory: number
  factor: number
  floorMs: number
  slowMs: number
  recoverAfter: number
}

export const DEFAULT_THRESHOLDS: Thresholds = {
  confirm: 2, window: 20, minHistory: 5, factor: 3.0, floorMs: 800, slowMs: 3000, recoverAfter: 3,
}

/**
 * Error kinds that mean "refused by OUR side" (proxy / firewall / policy), not a Microsoft outage.
 * The Python probe emits "proxy-denied". Which codes a Power Automate HTTP action emits when it is
 * blocked by policy is NOT documented (see DESIGN.md, unconfirmed items), so this list is deliberately
 * small and matched exactly.
 */
export const BLOCKED_KINDS: ReadonlySet<string> = new Set(['proxy-denied', 'blocked'])

/** "200,401,403" -> [200,401,403]; '' / null / 'any' -> null. Anything unparsable is ignored. */
export function parseAliveCodes(text: string | null | undefined): number[] | null {
  if (text == null) return null
  const t = String(text).trim()
  if (!t || t.toLowerCase() === 'any') return null
  const out: number[] = []
  for (const part of t.split(/[\s,;]+/)) {
    if (/^[1-5][0-9]{2}$/.test(part)) out.push(Number(part))
  }
  return out.length ? out : null
}

export function formatAliveCodes(alive: number[] | null): string {
  return alive == null ? '' : alive.join(',')
}

/** Port of the state rules at the end of probe() in outagewatch.py. */
export function rawState(r: RawResult, alive: number[] | null, slowMs: number = DEFAULT_THRESHOLDS.slowMs): RawState {
  const code = r.httpStatus
  const kind = r.errorKind ?? ''
  if (code == null && BLOCKED_KINDS.has(kind)) return 'blocked'
  if (code == null || code >= 500 || code === 429) return 'down'
  if (alive != null && !alive.includes(code)) return 'degraded'
  if (r.elapsedMs > slowMs) return 'degraded'
  return 'up'
}

export interface ProbeResult { name: string; state: RawState; ms: number }

/** Port of class Monitor: early-warning layer on top of raw probe states. */
export class Monitor {
  readonly confirm: number
  readonly window: number
  readonly minHistory: number
  readonly factor: number
  readonly floorMs: number
  private hist = new Map<string, number[]>()
  private fails = new Map<string, number>()
  private state = new Map<string, State>()

  constructor(t: Partial<Thresholds> = {}) {
    this.confirm = t.confirm ?? DEFAULT_THRESHOLDS.confirm
    this.window = t.window ?? DEFAULT_THRESHOLDS.window
    this.minHistory = t.minHistory ?? DEFAULT_THRESHOLDS.minHistory
    this.factor = t.factor ?? DEFAULT_THRESHOLDS.factor
    this.floorMs = t.floorMs ?? DEFAULT_THRESHOLDS.floorMs
  }

  /** Median (upper) of the recent HEALTHY samples, or null until min_history samples exist. */
  baseline(name: string): number | null {
    const h = [...(this.hist.get(name) ?? [])].sort((a, b) => a - b)
    return h.length >= this.minHistory ? h[Math.floor(h.length / 2)] : null
  }

  /** Latency above this is a warning; null without a baseline. */
  warnMs(name: string): number | null {
    const b = this.baseline(name)
    return b == null ? null : Math.max(b * this.factor, b + this.floorMs)
  }

  /** Feed one round; returns ALL published states so far (like the Python dict copy). */
  step(results: ProbeResult[]): Record<string, State> {
    for (const r of results) {
      const n = r.name
      let st: State
      if (r.state === 'blocked' || r.state === 'unconfigured') {
        this.fails.set(n, 0)            // local policy / not set up: not an outage, never escalates
        st = r.state
      } else if (r.state === 'down') {
        const f = (this.fails.get(n) ?? 0) + 1
        this.fails.set(n, f)
        st = f >= this.confirm ? 'down' : 'suspect'
      } else {
        this.fails.set(n, 0)
        const base = this.baseline(n)
        const slow = base != null && r.ms > Math.max(base * this.factor, base + this.floorMs)
        st = r.state === 'degraded' || slow ? 'warning' : 'up'
        if (st === 'up') {              // only healthy samples shape the baseline
          const h = this.hist.get(n) ?? []
          h.push(r.ms)
          if (h.length > this.window) h.splice(0, h.length - this.window)
          this.hist.set(n, h)
        }
      }
      this.state.set(n, st)
    }
    return Object.fromEntries(this.state)
  }
}

export const LEVELS: Record<Level, number> = { ok: 0, caution: 1, freeze: 2 }

/** Port of Automation.target_level. */
export function targetLevel(state: Record<string, State>): Level {
  const v = new Set(Object.values(state))
  v.delete('blocked'); v.delete('unconfigured')
  if (v.has('down') || state['auth'] === 'suspect') return 'freeze'
  if (v.has('suspect') || v.has('warning')) return 'caution'
  return 'ok'
}

/** Port of class Automation (level state machine only: no freeze file, no hooks in a browser). */
export class Automation {
  level: Level = 'ok'
  private clean = 0
  constructor(readonly recoverAfter: number = DEFAULT_THRESHOLDS.recoverAfter) {}

  /** Returns the new level when it changed, else null. */
  step(state: Record<string, State>): Level | null {
    const want = targetLevel(state)
    let next: Level
    if (LEVELS[want] > LEVELS[this.level]) {
      next = want; this.clean = 0                     // escalate at once
    } else if (LEVELS[want] < LEVELS[this.level]) {
      this.clean += 1                                 // de-escalate slowly
      next = this.clean >= this.recoverAfter ? want : this.level
      if (next !== this.level) this.clean = 0
    } else {
      this.clean = 0; next = this.level
    }
    const changed = next !== this.level
    this.level = next
    return changed ? next : null
  }
}

const sorted = (a: Iterable<string>) => [...a].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))

/** Port of impact(): which sign-in dependent services are at risk. */
export function impact(state: Record<string, State>, dependsOnAuth: ReadonlySet<string>): string[] {
  const a = state['auth']
  if (a === 'down' || a === 'suspect') return sorted(Object.keys(state).filter((n) => dependsOnAuth.has(n) && n !== 'auth' && state[n] !== 'unconfigured'))
  return []
}

/** Port of copilot_note(). */
export function copilotNote(state: Record<string, State>, copilotNeeds: ReadonlySet<string>): string {
  const c = state['m365-copilot'] ?? 'up'
  if (c === 'up' || NEUTRAL.has(c)) return ''
  const under = sorted([...copilotNeeds].filter((n) => { const v = state[n] ?? 'up'; return v !== 'up' && !NEUTRAL.has(v) }))
  return under.length ? 'Copilot affected; underlying services also unhealthy: ' + under.join(', ') : ''
}

/** Capped name list (port of _names()): long lists stay readable. */
export function names(list: string[], limit = 8): string {
  return list.slice(0, limit).join(', ') + (list.length > limit ? ` and ${list.length - limit} more` : '')
}

export interface DiagnoseText { allFailing: string; blocked: string; needsTenant: string }
/** Wording of the Python monitor (used by the golden cross-check to compare whole strings). */
export const PYTHON_TEXT: DiagnoseText = {
  allFailing: 'everything failing: check YOUR network/DNS first, then Microsoft',
  blocked: 'BLOCKED by your proxy/firewall (not a Microsoft outage): ',
  needsTenant: 'needs your tenant name: run with --tenant contoso (the name in contoso.sharepoint.com)',
}
/** Same sentences, adapted to where THIS monitor runs (a cloud flow, deployed by Deploy-OutageWatchPP). */
export const PP_TEXT: DiagnoseText = {
  allFailing: 'everything failing: check the probe flow and its network path first, then Microsoft',
  blocked: 'BLOCKED on our side (policy/proxy, not a Microsoft outage): ',
  needsTenant: 'needs your tenant name: re-run the deploy with -TenantName contoso (the name in contoso.sharepoint.com)',
}

/**
 * Port of diagnose(). Rules: unconfigured targets are ignored for the verdict and only counted at the end;
 * a blocked probe is reported but must never hide a real failure; long lists are capped.
 */
export function diagnose(results: { name: string; state: RawState }[], text: DiagnoseText = PP_TEXT): string {
  const s = results.filter((r) => r.state !== 'unconfigured')
  const unconf = results.filter((r) => r.state === 'unconfigured').length
  const blocked = s.filter((r) => r.state === 'blocked').map((r) => r.name)
  const bad = s.filter((r) => r.state !== 'up' && r.state !== 'blocked').map((r) => r.name)
  const auth = s.find((r) => r.name === 'auth')?.state
  let out: string
  if (!bad.length) out = blocked.length ? '' : 'all healthy'
  else if (bad.length === s.length) out = text.allFailing
  else if (auth !== undefined && auth !== 'up' && auth !== 'blocked') out = 'authentication degraded: sign-in dependent services will fail (Aug 31 pattern)'
  else out = 'partial outage: ' + names(bad)
  if (blocked.length) out += (out ? ' | ' : '') + text.blocked + names(blocked)
  if (unconf) out += ` | ${unconf} not set up (${text.needsTenant})`
  return out
}

/** Port of stress_score(): transparent 0-100 early-warning heuristic. Not a prediction. */
export function stressScore(samples: [State, number][], baseline: number | null, warnMs: number | null): number {
  const win = samples.slice(-10)
  const ok = win.filter(([st]) => st === 'up' || st === 'warning').map(([, ms]) => ms)
  let d = 0
  let j = 0
  if (baseline && ok.length) {
    const last = ok.slice(-3).sort((a, b) => a - b)
    if (warnMs && warnMs > baseline) d = Math.min(1, Math.max(0, (last[Math.floor(last.length / 2)] - baseline) / (warnMs - baseline)))
    if (ok.length >= 3) {
      let sum = 0
      for (let i = 1; i < ok.length; i++) sum += Math.abs(ok[i] - ok[i - 1])
      j = Math.min(1, sum / (ok.length - 1) / baseline)
    }
  }
  const f = Math.min(1, 0.5 * win.slice(-5).filter(([st]) => st === 'down' || st === 'suspect').length)
  return Math.floor(100 * Math.min(1, 0.5 * d + 0.2 * j + f) + 0.5)
}

/** [upstream, dependent] pairs (port of dependency_edges(), driven by the targets table flags). */
export function dependencyEdges(targets: TargetSpec[]): [string, string][] {
  const names = new Set(targets.map((t) => t.name))
  const out: [string, string][] = []
  if (names.has('auth')) for (const t of sorted(targets.filter((x) => x.dependsOnAuth && x.name !== 'auth').map((x) => x.name))) out.push(['auth', t])
  if (names.has('m365-copilot')) for (const t of sorted(targets.filter((x) => x.copilotNeeds && x.name !== 'm365-copilot').map((x) => x.name))) out.push([t, 'm365-copilot'])
  return out
}

// ---------------------------------------------------------------------------------------------
// Timeline: raw rows -> rounds -> published frames (what the dashboard renders)
// ---------------------------------------------------------------------------------------------

export interface RawRow extends RawResult {
  /** ISO timestamp of the probe. */
  at: string
  /** Round id written by the flow (the run's start time). Rows of one flow run share it. */
  round: string
}

export interface ServiceView {
  state: State
  raw: RawState
  ms: number
  code: number | null
  error: string | null
  baseline: number | null
  warnMs: number | null
}

export interface Frame {
  t: string
  level: Level
  levelChanged: Level | null
  verdict: string
  /** Services whose raw probe is fine but whose latency is far above their own baseline (Monitor-only warning). */
  early: string[]
  services: Map<string, ServiceView>
}

/** Group rows into rounds (oldest first). Duplicate target rows inside one round: the latest wins. */
export function groupRounds(rows: RawRow[]): { round: string; t: string; rows: RawRow[] }[] {
  const by = new Map<string, Map<string, RawRow>>()
  for (const r of rows) {
    const key = r.round || r.at
    let m = by.get(key)
    if (!m) { m = new Map(); by.set(key, m) }
    const prev = m.get(r.name)
    if (!prev || prev.at < r.at) m.set(r.name, r)
  }
  const rounds = [...by.entries()].map(([round, m]) => {
    const list = [...m.values()].sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0))
    const t = list.reduce((mx, r) => (r.at > mx ? r.at : mx), '')
    return { round, t, rows: list }
  })
  return rounds.sort((a, b) => (a.t < b.t ? -1 : a.t > b.t ? 1 : 0))
}

/**
 * Replay the stored raw facts through Monitor + Automation, oldest round first, exactly as the Python
 * run_cycle() would have done live. Deterministic: same rows in, same frames out.
 *
 * Honest limit: state before the oldest fetched row is unknown, so the first rounds of the window start
 * "cold" (no baseline, no failure streak), like a freshly started Python monitor.
 */
export function buildFrames(rows: RawRow[], targets: TargetSpec[], th: Partial<Thresholds> = {}): Frame[] {
  const T = { ...DEFAULT_THRESHOLDS, ...th }
  const spec = new Map(targets.map((t) => [t.name, t]))
  const dep = new Set(targets.filter((t) => t.dependsOnAuth).map((t) => t.name))
  const cop = new Set(targets.filter((t) => t.copilotNeeds).map((t) => t.name))
  const unconfigured = targets.filter((t) => t.unconfigured).map((t) => t.name)
  const unconfiguredSet = new Set(unconfigured)
  const mon = new Monitor(T)
  const auto = new Automation(T.recoverAfter)
  const frames: Frame[] = []
  const last = new Map<string, ServiceView>()
  for (const round of groupRounds(rows)) {
    const known = round.rows.filter((r) => spec.has(r.name) && !unconfiguredSet.has(r.name))
    if (!known.length) continue
    const results: ProbeResult[] = known.map((r) => ({ name: r.name, state: rawState(r, spec.get(r.name)!.alive, T.slowMs), ms: r.elapsedMs }))
    for (const u of unconfigured) results.push({ name: u, state: 'unconfigured', ms: 0 })   // like unconfigured_results(): present, neutral, never probed
    let verdict = diagnose(results)
    const state = mon.step(results)
    const hit = impact(state, dep)
    if (hit.length) verdict += ' | at risk: ' + hit.join(', ')
    const note = copilotNote(state, cop)
    if (note) verdict += ' | ' + note
    const changed = auto.step(state)
    if (changed) verdict += ' | LEVEL -> ' + changed
    known.forEach((r, i) => {
      last.set(r.name, {
        state: state[r.name], raw: results[i].state, ms: r.elapsedMs, code: r.httpStatus,
        error: r.errorKind || null, baseline: mon.baseline(r.name), warnMs: mon.warnMs(r.name),
      })
    })
    const early = results.filter((r) => r.state === 'up' && state[r.name] === 'warning').map((r) => r.name)
    for (const u of unconfigured) last.set(u, { state: 'unconfigured', raw: 'unconfigured', ms: 0, code: null, error: null, baseline: null, warnMs: null })
    frames.push({ t: round.t, level: auto.level, levelChanged: changed, verdict, early, services: new Map(last) })
  }
  return frames
}

/** Dashboard STALE rule: newest result older than 3x the probe interval. */
export function isStale(newestIso: string | null, intervalMinutes: number, nowMs: number): boolean {
  if (!newestIso) return false
  const t = Date.parse(newestIso)
  if (!Number.isFinite(t)) return true
  return nowMs - t > 3 * intervalMinutes * 60_000
}
